alter table public.award_spaces add column if not exists assurance_report_alert_days integer not null default 7 check(assurance_report_alert_days between 0 and 60);
create table if not exists public.election_governance_assurance_reporting_compliance(id uuid primary key default gen_random_uuid(),award_space_id uuid not null references public.award_spaces(id) on delete cascade,due_date date not null,status text not null default 'pending' check(status in('pending','due','overdue','submitted','approved','distributed')),report_id uuid references public.election_governance_assurance_reports(id) on delete set null,first_alerted_at timestamptz,last_alerted_at timestamptz,created_at timestamptz not null default now(),unique(award_space_id,due_date));
create index if not exists election_assurance_reporting_compliance_idx on public.election_governance_assurance_reporting_compliance(award_space_id,due_date,status);
alter table public.election_governance_assurance_reporting_compliance enable row level security;
